14	
15	double SARBackproject::total_time = 0;
16	double SARBackproject::total_avg_time = 0;
17	struct timespec SARBackproject::time_start = {0, 0};
18	struct timespec SARBackproject::time_end = {0, 0};
19	
20	SARBackproject::SARBackproject(const char* xclbin_filename, 
21	                               const char* st_dataset_filename, 
22	                               const char* rc_dataset_filename, 
23	                               const char* img_out_filename, 
24	                               int iter, 
25	                               int instances)
26	: m_xclbin_filename(xclbin_filename)
27	, m_st_dataset_filename(st_dataset_filename)
28	, m_rc_dataset_filename(rc_dataset_filename)
29	, m_img_out_filename(img_out_filename)
30	, m_iter(iter)
31	, m_instances(instances)
32	, m_device(0)
33	, m_uuid(m_device.load_xclbin(this->m_xclbin_filename))
34	, m_broadcast_data_buffer(m_device, PULSES*BC_ELEMENTS*sizeof(float), xrt::bo::flags::normal, 0)
35	, m_broadcast_data_array(m_broadcast_data_buffer.map<float*>())
36	, m_xyz_px_buffer(m_device, PULSES*RC_SAMPLES*sizeof(float)*3, xrt::bo::flags::normal, 0)
37	, m_xyz_px_array(m_xyz_px_buffer.map<float*>())
38	, m_rc_buffer(m_device, PULSES*RC_SAMPLES*sizeof(cfloat), xrt::bo::flags::normal, 0)
39	, m_rc_array(m_rc_buffer.map<cfloat*>())
40	{
41	
42	    // Instantiate kernels, handlers, and buffers for multiple instances
43	    // TODO: Instances wont work right if it is greater than 1. This is fine
44	    // for now since there are no plans to instantiate the design more than
45	    // once, but would be nice if this still worked for future proofing
46	    for(int i = 0; i < this->m_instances; i++) {
